class A { A() { System.out.print("A"); } }
class B extends A { B() { System.out.print("B"); } }
class C extends B { C() { System.out.println("C"); } }

class Main {
    public static void main(String[] args) {
        new C();
    }
}

class Fare { int cost() { return 40; } }
class Reduced extends Fare {
    @Override
    int cost() { return super.cost() - 5; }
}

class Main {
    public static void main(String[] args) {
        System.out.println(new Reduced().cost());
    }
}

class Parent {
    private final int number;
    Parent(int number) { this.number = number; }
    int value() { return number; }
}
class Child extends Parent {
    Child(int number) { super(number + 1); }
}

class Main {
    public static void main(String[] args) {
        System.out.println(new Child(9).value());
    }
}
